using Astrea.BattleActions;
using NaughtyAttributes;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "KarmaEffect", menuName = "Data/Battle/Effects/Orion/Karma Effect")]
public class KarmaEffect : Effect
{
	[Header("Karma")]
	[SerializeField]
	private int corruptionAmount;

	[SerializeField]
	private int amountToTriggerKarma;

	[Header("Corrupted Karma")]
	[SerializeField]
	private bool corruptedKarma;

	[Header("Description")]
	[SerializeField]
	private CorruptAction corruptAction;

	[Header("Karma Modifier Effects")]
	[SerializeField]
	[HideIf("corruptedKarma")]
	private BaseDecreaseActivationAmountEffect guiltEffect;

	[SerializeField]
	[HideIf("corruptedKarma")]
	private BaseDecreaseActivationAmountEffect forgivenessEffect;

	[Header("Effects To Activate On Karma Triggered")]
	[SerializeField]
	[HideIf("corruptedKarma")]
	private Effect[] effectsToActivateOnDebtTriggered;

	public int AmountToTriggerKarma => amountToTriggerKarma;

	private UnitEffects unitEffects => ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<UnitEffects>();

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		string activationDescription = Smart.Format(corruptAction.GetActionDescription(-4), GetKarmaCorruptionModifierText());
		return base.localizationManager.GetLocalizedWhenReachEffectActivateBaseFormatted(GetKarmaTriggerModifierText(), this, activationDescription, GetKarmaTriggerModifierText()) + (corruptedKarma ? "" : ("\n" + base.localizationManager.GetLocalizedCorruptionNotIncreasedByCorruptionModifier()));
	}

	private string GetKarmaTriggerModifierText()
	{
		int guiltEffectAmount = GetGuiltEffectAmount(activateFeedback: true);
		if (guiltEffectAmount > 0)
		{
			return amountToTriggerKarma - guiltEffectAmount + $"({amountToTriggerKarma}-{guiltEffectAmount})";
		}
		return amountToTriggerKarma.ToString();
	}

	private int GetGuiltEffectAmount(bool activateFeedback)
	{
		if (corruptedKarma)
		{
			return 0;
		}
		if (!base.isOnBattleScene)
		{
			return 0;
		}
		return unitEffects.IsEffectActiveGetAmount(guiltEffect, activateFeedback);
	}

	private string GetKarmaCorruptionModifierText()
	{
		int forgivenessEffectAmount = GetForgivenessEffectAmount(activateFeedback: true);
		if (forgivenessEffectAmount > 0)
		{
			return corruptionAmount - forgivenessEffectAmount + $"({corruptionAmount}-{forgivenessEffectAmount})";
		}
		return corruptionAmount.ToString();
	}

	private int GetForgivenessEffectAmount(bool activateFeedback)
	{
		if (corruptedKarma)
		{
			return 0;
		}
		if (!base.isOnBattleScene)
		{
			return 0;
		}
		return unitEffects.IsEffectActiveGetAmount(forgivenessEffect, activateFeedback);
	}

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		EffectIncreased(effectAmount, effectOwner, source);
	}

	public override void EffectIncreased(int effectAmount, GameObject effectOwner, GameObject source)
	{
		int num = amountToTriggerKarma - GetGuiltEffectAmount(activateFeedback: false);
		if (effectAmount >= num)
		{
			int num2 = Mathf.FloorToInt((float)effectAmount / (float)num);
			int amount = num2 * num;
			UnitEffects component = effectOwner.GetComponent<UnitEffects>();
			for (int i = 0; i < num2; i++)
			{
				if (!corruptedKarma)
				{
					effectOwner.GetComponent<CorruptionStats>().Corrupt(corruptionAmount - GetForgivenessEffectAmount(activateFeedback: false), null, CorruptionPurifyModifierEnum.CANTBEINCREASEDCORRUPTION);
				}
				else
				{
					ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<CorruptionStats>().Corrupt(corruptionAmount, null, CorruptionPurifyModifierEnum.NONE, playSFX: true);
				}
				if (!corruptedKarma)
				{
					for (int j = 0; j < effectsToActivateOnDebtTriggered.Length; j++)
					{
						component.IsEffectActiveWithActivation(effectsToActivateOnDebtTriggered[j]);
					}
				}
			}
			component.IsEffectActive(this);
			component.IsEffectActiveAndDecreaseEffect(this, amount, activateFeedback: false);
			PlaySecondEffectActivationSFX();
			SpawnSecondVFX(GetVFXOwnerPosition(effectOwner), 3f);
		}
		else
		{
			PlayEffectActivationSFX();
			SpawnVFX(GetVFXOwnerPosition(effectOwner), 3f);
		}
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		EffectIncreased(effectAmount, effectOwner, null);
		return effectAmount;
	}
}
